@push('head')<meta name="csrf-token" content="{{ csrf_token() }}">@endpush
@push('scripts')<script>
(function(){const csrf=document.querySelector('meta[name="csrf-token"]')?.content;const toggleUrl=id=>'{{ url('/admin/site-content/navigation/toggle') }}/'+id;document.querySelectorAll('.nav-toggle').forEach(button=>{button.addEventListener('click',async()=>{const enabled=button.dataset.enabled!=='1';button.disabled=true;try{const res=await fetch(toggleUrl(button.dataset.id),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({enabled})});if(!res.ok)throw new Error();window.location.reload()}catch(e){button.disabled=false;alert('Could not update navigation. Please try again.')}})});const list=document.querySelector('.company-list');if(!list)return;let dragged=null;list.querySelectorAll('.row.nav-enabled').forEach(row=>{row.addEventListener('dragstart',e=>{dragged=row;row.classList.add('dragging');e.dataTransfer.effectAllowed='move'});row.addEventListener('dragend',async()=>{row.classList.remove('dragging');if(!dragged)return;const ids=[...list.querySelectorAll('.row.nav-enabled')].map(el=>el.dataset.id);try{const res=await fetch('{{ route('admin.site-content.navigation.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({ids})});if(!res.ok)throw new Error()}catch(e){window.location.reload()}dragged=null});row.addEventListener('dragover',e=>{e.preventDefault();if(!dragged||dragged===row)return;const rect=row.getBoundingClientRect();if(e.clientY>rect.top+rect.height/2)row.after(dragged);else row.before(dragged)})})})();
</script>@endpush
